std::vector<Person> active;
std::copy_if(people.begin(), people.end(), std::back_inserter(active),
             [](const Person& p) { return p.active; });

std::vector<std::string> emails;
std::transform(active.begin(), active.end(), std::back_inserter(emails),
               [](const Person& p) { return p.email; });

auto total = std::accumulate(emails.begin(), emails.end(), std::size_t{0},
    [](std::size_t n, const std::string& e) { return n + e.size(); });
